# -*- coding: utf-8 -*-
from contextlib import contextmanager


class Logger(object):
    def __init__(self, cmd_executor, capture_condition_tracker):
        self._cmd_executor = cmd_executor
        self._capture_condition_tracker = capture_condition_tracker

        self._start()

    def close(self):
        self._cmd_executor.stop()

    @contextmanager
    def capture_until(self, condition, timeout=30):
        msgs = []
        with self._cmd_executor.get_output() as output:
            yield msgs
            self._capture_condition_tracker.wait_for_condition(
                output, condition, timeout)
            msgs.extend(self._capture_condition_tracker.captured_packets)

    def _start(self):
        try:
            self._cmd_executor.start()
        except BaseException:
            self.close()
            raise
